INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助け、応援", 155, 0, "ヒヨリ", 100101, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 8, "A", 16, 2, "トゥインクルウィッシュ", "獣人族", "人助けが大好き！　前向き格闘娘", 44, "東山奈央");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("料理、人間観察", 158, 0, "ユイ", 100201, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 4, "O", 17, 2, "トゥインクルウィッシュ", "ヒューマン", "戦闘のサポートが得意な、心優しい少女", 47, "種田梨沙");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、乗馬、お茶", 163, 0, "レイ", 100301, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 1, "B", 18, 2, "トゥインクルウィッシュ", "魔族", "クールで何事にも真っ直ぐな剣士", 46, "早見沙織");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("いたずら、探検", 128, 0, "ミソギ", 100401, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 10, 8, "O", 9, 5, "リトルリリカル", "ヒューマン", "探検好きのイタズラっ子", 27, "諸星すみれ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ヒーローごっこ", 146, 0, "マツリ", 100501, "？？？", 25, 11, "O", 12, 8, "王宮騎士団（NIGHTMARE）", "獣人族", "ヒーローに憧れる騎士見習いの少女", 40, "下田麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("サックス", 150, 0, "アカリ", 100601, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 22, 11, "O", 13, 7, "悪魔偽王国軍（ディアボロス）", "魔族", "甘え上手なみんなの人気者", 42, "浅倉杏美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("プリンを食べること", 130, 0, "ミヤコ", 100701, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 23, 1, "B", 14, 7, "悪魔偽王国軍（ディアボロス）", "魔族", "プリン大好きゴースト娘", 32, "雨宮天");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("鏡で自分を見ること", 150, 0, "ユキ", 100801, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 10, 10, "AB", 14, 15, "ヴァイスフリューゲル　ランドソル支部", "エルフ", "ボクは誰よりも美しい", 40, "大空直美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("小説執筆", 159, 0, "アンナ", 100901, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 5, 7, "A", 17, 13, "トワイライトキャラバン", "魔族", "前世を信じる中二病患者、「疾風の冥姫」", 45, "髙野麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("空想、ぬいぐるみ集め", 155, 0, "マホ", 101001, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 22, 9, "O", 16, 10, "自警団（カォン）", "獣人族", "マホマホ王国のプリンセス", 42, "内田真礼");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お裁縫", 156, 0, "リノ", 101101, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 25, 8, "A", 15, 3, "ラビリンス", "ヒューマン", "人懐っこくてマシンガントークな妹系少女", 44, "阿澄佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("妹と遊ぶこと、二度寝、昼寝、早寝", 156, 0, "ハツネ", 101201, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 24, 12, "A", 17, 6, "フォレスティエ", "エルフ", "みんなのために超能力を使う眠り姫", 46, "大橋彩香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、魔法", 166, 0, "ナナカ", 101301, "", 21, 8, "O", 18, 13, "トワイライトキャラバン", "魔族", "オタク全開な魔法少女", 55, "佳村はるか");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、推理", 152, 0, "カスミ", 101401, "test", 3, 11, "AB", 15, 10, "自警団（カォン）", "獣人族", "頭脳明晰な美少女名探偵", 41, "水瀬いのり");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("絵本作り", 165, 0, "ミサト", 101501, "test", 5, 9, "O", 21, 6, "フォレスティエ", "エルフ", "母性溢れる優しいみんなの「ミサト先生」", 54, "國府田マリ子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ファッション", 167, 0, "スズナ", 101601, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 10, 4, "O", 17, 14, "ルーセント学院", "魔族", "天真爛漫で人気者のカリスマモデル", 48, "上坂すみれ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("踊り、空手", 158, 0, "カオリ", 101701, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 7, 7, "A", 17, 10, "自警団（カォン）", "獣人族", "いつでも「なんくるないさ～」な天然娘", 53, "高森奈津美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 162, 0, "イオ", 101801, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 14, 8, "B", 23, 14, "ルーセント学院", "魔族", "多くの男性を魅了する無垢な女教師", 52, "伊藤静");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("かわいいもの集め", 117, 0, "ミミ", 102001, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 3, 4, "O", 10, 5, "リトルリリカル", "獣人族", "お歌もにんじんも、ウサギさんも大好き♪", 21, "日高里菜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("観劇、おままごと", 150, 0, "クルミ", 102101, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 9, 6, "B", 12, 9, "サレンディア救護院", "ヒューマン", "泣き虫で臆病な守ってあげたい女の子", 40, "植田佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ゲーム全般", 150, 0, "ヨリ", 102201, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 22, 11, "O", 13, 7, "悪魔偽王国軍（ディアボロス）", "魔族", "人見知りであまのじゃくな女の子", 40, "原紗友里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("屋内でできる遊び", 148, 0, "アヤネ", 102301, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 10, 5, "B", 14, 9, "サレンディア救護院", "ヒューマン", "ぷうきちといつも一緒！", 38, "芹澤優");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ご奉仕", 154, 0, "スズメ", 102501, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 12, 12, "O", 15, 9, "サレンディア救護院", "ヒューマン", "お嬢さまのためにがんばるドジっ娘メイド", 43, "悠木碧");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("あんパン", 144, 0, "リン", 102601, "test", 1, 1, "B", 17, 11, "牧場（エリザベスパーク）", "獣人族", "遊びと睡眠が何より大事なぐうたら娘", 42, "小岩井ことり");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("実験、裁縫、料理", 154, 0, "エリコ", 102701, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 30, 7, "B", 16, 13, "トワイライトキャラバン", "魔族", "運命の相手に一途すぎる乙女", 43, "橋本ちなみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("経営、お茶会", 156, 0, "サレン", 102801, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 4, 10, "A", 17, 9, "サレンディア救護院", "エルフ", "救護院を経営する優しい庶民派お嬢様", 43, "堀江由衣");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("舞台鑑賞、ダンス", 157, 0, "ノゾミ", 102901, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 24, 1, "B", 17, 4, "カルミナ", "ヒューマン", "歌って踊れる大人気アイドル", 40, "日笠陽子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("忍法開発", 163, 0, "ニノン", 103001, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 31, 8, "O", 16, 15, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "トーゴクの神秘、オシエテクダサイ！", 51, "佐藤聡美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("占い", 157, 0, "シノブ", 103101, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 22, 12, "AB", 18, 7, "悪魔偽王国軍（ディアボロス）", "魔族", "占いが得意な霊能少女", 42, "大坪由佳");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("慈善事業", 157, 0, "アキノ", 103201, "この私とともにいる限り、\nお金に不自由はさせませんわ！", 12, 3, "AB", 18, 12, "メルクリウス財団", "ヒューマン", "一人前の商人を目指すパワフルお嬢様", 45, "松嵜麗");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("漫才", 142, 0, "マヒル", 103301, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 3, 3, "B", 20, 11, "牧場（エリザベスパーク）", "ヒューマン", "みんなを笑顔にするお笑い牧場主", 35, "新田恵海");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ウインドーショッピング", 164, 0, "ユカリ", 103401, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 16, 3, "A", 22, 12, "メルクリウス財団", "エルフ", "純情でほっとけない大人の女性", 55, "今井麻美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お勉強", 118, 0, "キョウカ", 103601, "test", 2, 2, "A", 8, 5, "リトルリリカル", "エルフ", "礼儀正しくしっかり者のちびっ子優等生", 21, "小倉唯");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("剣術、年長者をからかう", 149, 0, "トモ", 103701, "test", 11, 8, "A", 13, 8, "王宮騎士団（NIGHTMARE）", "ヒューマン", "義理堅くてからかい好きな剣術少女", 43, "茅原実里");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、お散歩", 153, 0, "シオリ", 103801, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 3, 11, "A", 14, 11, "牧場（エリザベスパーク）", "獣人族", "読書が趣味の病弱少女", 40, "小清水亜美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("友達作りのイメトレ", 158, 0, "アオイ", 104001, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 6, 6, "AB", 13, 6, "フォレスティエ", "エルフ", "「友達」に憧れる、エルフの森の女の子", 44, "花澤香菜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("各種楽器", 163, 0, "チカ", 104201, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 3, 6, "O", 17, 4, "カルミナ", "ヒューマン", "人々を守るために歌う、唱喚士の少女", 46, "福原綾香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("お菓子作り", 168, 0, "マコト", 104301, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 9, 8, "O", 17, 10, "自警団（カォン）", "獣人族", "男勝りで情に厚いワイルド娘", 54, "小松未可子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("世界征服", 172, 0, "イリヤ", 104401, "test", 5, 5, "A", "??", 7, "悪魔偽王国軍（ディアボロス）", "魔族", "かつては夜を支配した最強の吸血鬼", 50, "丹下桜");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("小説を読むこと", 157, 0, "クウカ", 104501, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 19, 11, "AB", 18, 15, "ヴァイスフリューゲル　ランドソル支部", "ヒューマン", "妄想大好き！　ほんとは照れ屋な女の子", 49, "長妻樹里");
