INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("格闘技、湯浴み", 171, 0, "ジュン", 104701, "？？？", 25, 10, "A", 25, 8, "王宮騎士団（NIGHTMARE）", "ヒューマン", "素顔を見せない冷静沈着な女性騎士", 50, "川澄綾子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("傭兵などのアルバイト", 163, 0, "ミフユ", 104801, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 11, 11, "O", 20, 12, "メルクリウス財団", "ヒューマン", "仕事も私事も効率優先な傭兵少女", 49, "田所あずさ");
