INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("占い", 157, 0, "シノブ（ハロウィン）", 108101, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 22, 12, "AB", 18, 7, "悪魔偽王国軍（ディアボロス）", "魔族", "占いが得意な霊能少女", 42, "大坪由佳");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("プリンを食べること", 130, 0, "ミヤコ（ハロウィン）", 108201, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 23, 1, "B", 14, 7, "悪魔偽王国軍（ディアボロス）", "魔族", "プリン大好きゴースト娘", 32, "雨宮天");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ファッション誌鑑賞、コスメ集め", 120, 0, "ミサキ（ハロウィン）", 108301, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 3, 1, "A", 11, 14, "ルーセント学院", "魔族", "ちょっとおませな恋に恋する女の子", 22, "久野美咲");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("各種楽器", 163, 0, "チカ（クリスマス）", 108401, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 3, 6, "O", 17, 4, "カルミナ", "ヒューマン", "人々を守るために歌う、唱喚士の少女", 46, "福原綾香");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("観劇、おままごと", 150, 0, "クルミ（クリスマス）", 108501, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 9, 6, "B", 12, 9, "サレンディア救護院", "ヒューマン", "泣き虫で臆病な守ってあげたい女の子", 40, "植田佳奈");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("屋内でできる遊び", 148, 0, "アヤネ（クリスマス）", 108601, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 10, 5, "B", 14, 9, "サレンディア救護院", "ヒューマン", "ぷうきちといつも一緒！", 38, "芹澤優");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助け、応援", 155, 0, "ヒヨリ（ニューイヤー）", 108701, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 8, "A", 16, 2, "トゥインクルウィッシュ", "獣人族", "人助けが大好き！　前向き格闘娘", 44, "東山奈央");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("料理、人間観察", 158, 0, "ユイ（ニューイヤー）", 108801, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 4, "O", 17, 2, "トゥインクルウィッシュ", "ヒューマン", "戦闘のサポートが得意な、心優しい少女", 47, "種田梨沙");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、乗馬、お茶", 163, 0, "レイ（ニューイヤー）", 108901, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 1, "B", 18, 2, "トゥインクルウィッシュ", "魔族", "クールで何事にも真っ直ぐな剣士", 46, "早見沙織");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("実験、裁縫、料理", 154, 0, "エリコ（バレンタイン）", 109001, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 30, 7, "B", 16, 13, "トワイライトキャラバン", "魔族", "運命の相手に一途すぎる乙女", 43, "橋本ちなみ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("家事全般", 168, 0, "シズル（バレンタイン）", 109101, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 24, 10, "O", 18, 3, "ラビリンス", "ヒューマン", "お姉ちゃんがお世話してあげるからねっ！", 54, "生天目仁美");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書", 156, 0, "アン", 109201, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 1, 12, "AB", 17, "", "？？？", "ヒューマン", "英霊と契約を結んだマナリアの天才王女", 55, "日笠陽子");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("食べること、眠ること", 144, 0, "ルゥ", 109301, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 4, 2, "O", 16, "", "？？？", "ヒューマン", "マナリア魔法学院の新入生", 45, "こやまきみこ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("ピアノ", 167, 0, "グレア", 109401, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 3, 11, "B", 17, "", "？？？", "半人半竜", "人を超越した力を有す心優しい竜姫", 67, "福原綾香");
