INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("人助け、応援", 155, 0, "ヒヨリ（サマー）", 122401, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 27, 8, "A", 16, 2, "トゥインクルウィッシュ", "獣人族", "人助けが大好き！　前向き格闘娘", 44, "東山奈央");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("読書、乗馬、お茶", 163, 0, "レイ（サマー）", 122501, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 12, 1, "B", 18, 2, "トゥインクルウィッシュ", "魔族", "クールで何事にも真っ直ぐな剣士", 46, "早見沙織");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES ("料理、人間観察", 158, 0, "ユイ（サマー）", 122601, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 5, 4, "O", 17, 2, "トゥインクルウィッシュ", "ヒューマン", "戦闘のサポートが得意な、心優しい少女", 47, "種田梨沙");
